use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource;
class VolunteerVisitResource extends JsonResource { public function toArray(Request $request): array { return ['id'=>$this->id,'volunteer_id'=>$this->volunteer_id,'citizen_id'=>$this->citizen_id,'family_id'=>$this->family_id,'village_id'=>$this->village_id,'ward_id'=>$this->ward_id,'visit_type'=>$this->visit_type,'status'=>$this->status,'scheduled_at'=>$this->scheduled_at?->toIso8601String(),'checked_in_at'=>$this->checked_in_at?->toIso8601String(),'checked_out_at'=>$this->checked_out_at?->toIso8601String(),'check_in_latitude'=>$this->check_in_latitude,'check_in_longitude'=>$this->check_in_longitude,'check_out_latitude'=>$this->check_out_latitude,'check_out_longitude'=>$this->check_out_longitude,'notes'=>$this->notes,'outcome'=>$this->outcome,'follow_up_required'=>(bool)$this->follow_up_required,'follow_up_date'=>$this->follow_up_date?->toDateString(),'follow_up_notes'=>$this->follow_up_notes,'attachments'=>collect($this->attachments??[])->keys()->map(fn($i)=>['index'=>$i,'download_url'=>url("/api/volunteer-visits/{$this->id}/attachments/{$i}")])->values(),'volunteer'=>$this->whenLoaded('volunteer'),'citizen'=>$this->whenLoaded('citizen'),'family'=>$this->whenLoaded('family'),'village'=>$this->whenLoaded('village'),'ward'=>$this->whenLoaded('ward'),'activity_logs'=>$this->whenLoaded('activityLogs')]; } }
